#!/usr/bin/env python3
"""Assemble the paper-repo delivery tree: python scripts/package_delivery.py <dest> [--raw-tar PATH]
dest/code/{src,scripts,requirements.lock}, dest/results/{summary,tables,*.csv,FINDINGS.md,MANIFEST.md}, dest/REPRODUCE.md.
Raw per-replicate files and the Louvain cache stay out (see REPRODUCE.md section 7)."""
import hashlib, os, shutil, subprocess, sys
import sys as _s
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.abspath(os.path.join(HERE, ".."))
dest = os.path.abspath(sys.argv[1]); raw_tar = sys.argv[sys.argv.index("--raw-tar") + 1] if "--raw-tar" in sys.argv else None
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
ign = shutil.ignore_patterns("__pycache__", "*.pyc")
for sub in ("code/src", "code/scripts", "code/tests", "results/summary", "results/tables", "results/compact"):
    shutil.rmtree(os.path.join(dest, sub), ignore_errors=True)
shutil.copytree(os.path.join(ROOT, "src"), os.path.join(dest, "code", "src"), ignore=ign)
shutil.copytree(os.path.join(ROOT, "scripts"), os.path.join(dest, "code", "scripts"), ignore=ign)
shutil.copytree(os.path.join(ROOT, "tests"), os.path.join(dest, "code", "tests"), ignore=ign)
shutil.copy(os.path.join(ROOT, "requirements.lock"), os.path.join(dest, "code", "requirements.lock"))
shutil.copytree(os.path.join(ROOT, "results", "summary"), os.path.join(dest, "results", "summary"))
shutil.copytree(os.path.join(ROOT, "results", "tables"), os.path.join(dest, "results", "tables"))
shutil.copytree(os.path.join(ROOT, "results", "compact"), os.path.join(dest, "results", "compact"))
for f in ("COMPLETENESS.csv", "CELLS_NOT_RUN.csv", "RUNTIME.csv", "hypotheses.csv", "hypotheses_postfreeze.csv", "FINDINGS.md"):
    if os.path.exists(os.path.join(ROOT, "results", f)):
        shutil.copy(os.path.join(ROOT, "results", f), os.path.join(dest, "results", f))
shutil.copy(os.path.join(ROOT, "REPRODUCE.md"), os.path.join(dest, "REPRODUCE.md"))

GEN = {"summary/theory_vs_sim_e9.csv": ("code/scripts/theory_bias.py", "results/summary/e9.csv"), "hypotheses.csv": ("code/scripts/findings.py", "results/summary/*.csv, results/summary/theory_vs_sim_e9.csv"),
       "COMPLETENESS.csv": ("code/scripts/completeness.py", "results/raw/*"), "CELLS_NOT_RUN.csv": ("code/scripts/completeness.py", "results/raw/*"),
       "hypotheses_postfreeze.csv": ("code/scripts/post_freeze.py", "results/summary/e11.csv, e12.csv, e13.csv"), "RUNTIME.csv": ("code/scripts/runtime_table.py", "results/raw/*"), "FINDINGS.md": ("hand-written from hypotheses.csv and results/tables", "results/hypotheses.csv, results/tables/*")}
TABLE_GEN = {f"tables/{k}.csv": v for k, v in {
    "t17_variance_law": ("code/scripts/variance_law.py", "results/summary/e1.csv; graphs regenerated from the cell seeds"), "t17b_variance_law_e3": ("code/scripts/variance_law.py", "results/summary/e3.csv"),
    "t17c_variance_law_components": ("code/scripts/variance_law.py", "results/summary/e21.csv"), "t18_exposure_variation": ("code/scripts/exposure_diagnostics.py", "graphs and designs regenerated from the cell seeds (e4, e19)"),
    "t19_coverage_expectation": ("code/scripts/coverage_analysis.py", "results/compact/e6, e15 (raw e6, e15)"), "t19b_coverage_by_se_type": ("code/scripts/coverage_analysis.py", "results/compact/e6, e15 (raw e6, e15)"),
    "t20_variance_components": ("code/scripts/world_uncertainty.py", "results/raw/e2, e18"), "t20b_worlds_needed": ("code/scripts/world_uncertainty.py", "results/raw/e18"),
    "t20c_headline_intervals": ("code/scripts/world_uncertainty.py", "results/raw/e1"), "t21_crossover": ("code/scripts/crossover.py", "results/summary/e17.csv"),
    "t21b_crossover_scaling": ("code/scripts/crossover.py", "results/summary/e17.csv"), "t22_factor_anova": ("code/scripts/factor_anova.py", "results/summary/e20.csv"),
    "t22b_factor_anova_interactions": ("code/scripts/factor_anova.py", "results/summary/e20.csv"), "t23_heavy_tail": ("code/scripts/heavy_tail.py", "results/summary/e14.csv; graphs regenerated from the cell seeds"),
    "t24_cluster_hajek": ("code/scripts/cluster_hajek.py", "results/summary/e19.csv"), "t25_estimator_scope": ("code/scripts/estimator_scope.py", "results/summary/e2.csv, e16.csv"),
    "t25b_estimator_scope_cells": ("code/scripts/estimator_scope.py", "results/summary/e2.csv, e16.csv"),
    "t14_gamma_dependence": ("code/scripts/post_freeze.py", "results/summary/e11.csv"), "t15_hajek": ("code/scripts/post_freeze.py", "results/summary/e12.csv"), "t16_second_seed": ("code/scripts/post_freeze.py", "results/summary/e13.csv, e4.csv, e2.csv, e6.csv")}.items()}
lines = ["# Manifest of `results/`", "", "Generated by `code/scripts/package_delivery.py`. Every file: sha256, generating script, inputs. Seeds are fixed per grid cell in `code/src/netgate/experiments.py` (see REPRODUCE.md section 3).", ""]
if raw_tar:
    lines += [f"Raw per-replicate results: release `raw-results` of `experiment-repo`, `{os.path.basename(raw_tar)}`, sha256 `{sha(raw_tar)}`.", ""]
lines += ["| file | sha256 | generated by | inputs |", "|---|---|---|---|"]
for dp, _, fs in sorted(os.walk(os.path.join(dest, "results"))):
    for f in sorted(fs):
        p = os.path.join(dp, f); rel = os.path.relpath(p, os.path.join(dest, "results"))
        if rel == "MANIFEST.md": continue
        if rel in GEN: g, i = GEN[rel]
        elif rel.startswith("compact/"): g, i = "code/scripts/compact.py", f"results/raw/{f.split('.')[0]}/*.csv.gz"
        elif rel in TABLE_GEN: g, i = TABLE_GEN[rel]
        elif rel.startswith("summary/"): g, i = "code/scripts/aggregate.py", f"results/raw/{f.split('.')[0]}/*.csv.gz"
        elif rel == "tables/t11_factor_ranking.csv": g, i = "code/scripts/factor_ranking.py", "results/summary/e1,e2,e3,e5.csv"
        elif rel.startswith("tables/"): g, i = "code/scripts/make_tables.py", "results/summary/*.csv"
        else: g, i = "?", "?"
        lines.append(f"| `results/{rel}` | `{sha(p)[:16]}…` | `{g}` | {i} |")
try:
    head = subprocess.run(["git", "-C", ROOT, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    lines += ["", f"experiment-repo revision the code was taken from: `{head}` (working tree may be ahead; the code files in `code/` are the ones that produced these files)."]
except Exception:
    pass
open(os.path.join(dest, "results", "MANIFEST.md"), "w").write("\n".join(lines) + "\n")
print("packaged ->", dest)
